{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C14"],
      "claim": "Cilomilast, a close structural analogue with high assay transfer, has a mean absolute oral bioavailability of 96% (range 92–102%) in healthy humans, directly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Levomilnacipran, another high-transfer analogue, shows 92% absolute oral bioavailability in healthy volunteers, supporting high systemic exposure after oral dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Rolipram, a high-transfer analogue, is completely absorbed orally with an absolute bioavailability of 73 ± 25% in humans, supporting F well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Ethinyl estradiol, a steroid analogue with high transfer, has oral bioavailability of about 25–65% in women; although lower than other analogues, it still exceeds the 20% threshold and supports a high classification.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "A structurally related steroidal compound was projected to have moderate-to-high human oral bioavailability of approximately 40–70%, supporting the query's high-F classification.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferred experimental evidence, including multiple absolute bioavailability measurements in humans, indicates oral bioavailability well above 20% (mostly 68–100%). The high assay-transfer scores and consistent direction outweigh the uncertain physicochemical prior.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule.",
    "The impact of the query's high lipophilicity and low solubility on absorption is not directly tested.",
    "First-pass metabolism of the ester/acetyl groups is not experimentally characterized."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

